import org.junit.jupiter.params.provider.ValueSource;

/** Node-only prefix counts traverse predicate cardinalities instead of every member of each node group. */
class LmdbPersistentAdjacencyNodeGroupWorkTest {

	private static final long FIRST_NODE = 100;
	private static final long SECOND_NODE = 200;
	private static final long FIRST_PREDICATE = 20;
	private static final long FIRST_NEIGHBOR = 10_000;

	@TempDir
	Path directory;

	@ParameterizedTest(name = "incoming={0}")
	@ValueSource(booleans = { false, true })
	void nodeOnlyGroupsFetchOneRepresentativeAndCountThePredicateDirectory(boolean incoming) throws Exception {
		Work small = groupedWork(directory.resolve("small"), incoming, 8);
		Work large = groupedWork(directory.resolve("large"), incoming, LmdbPersistentAdjacency.PAGE_QUADS);
		assertAll(
				() -> assertThat(small.representatives()).as("small groups use only their two representatives")
						.isEqualTo(2),
				() -> assertThat(large.representatives()).as("group size must not increase representative scans")
						.isEqualTo(2),
				() -> assertThat(small.metadataAnswers()).as("one directory sum answers each node count").isEqualTo(2),
				() -> assertThat(large.metadataAnswers()).isEqualTo(2),
				() -> assertThat(small.pointReads()).as("a directory sum is not a scalar metadata get").isZero(),
				() -> assertThat(large.pointReads()).isZero(),
				() -> assertThat(large.cursorOpens()).as("directory count cursors are independent of group degree")
						.isEqualTo(small.cursorOpens())
						.isLessThanOrEqualTo(8),
				() -> assertThat(small.cursorReads()).as("directory cardinalities require real native cursor reads")
						.isPositive()
						.isLessThanOrEqualTo(32),
				() -> assertThat(large.cursorReads())
						.as("separate pages at node boundaries permit only bounded predecessor positioning work")
						.isPositive()
						.isLessThanOrEqualTo(small.cursorReads() + 2));
	}

	/** Full-key boundaries and a residual context must keep their existing exact streaming fallback. */
	@ParameterizedTest(name = "incoming={0}")
	@ValueSource(booleans = { false, true })
	void partialNodeGroupsAndResidualContextKeepExactCounts(boolean incoming) throws Exception {
		int degree = 17;
		int midpoint = degree / 2;
		try (Fixture fixture = new Fixture(directory, incoming, degree); Txn txn = fixture.snapshot()) {
			LmdbPrefixRunPlan plan = fixture.plan(-1);
			try (LmdbPrefixRunCursor cursor = fixture.store.getPrefixRuns(txn, plan, -1, -1, -1, -1, true, true)) {
				assertThat(cursor.seekTo(new long[] { FIRST_NODE, FIRST_PREDICATE, FIRST_NEIGHBOR + midpoint, 0 }))
						.isTrue();
				assertThat(groups(cursor, fixture.groupField)).containsExactly(
						new Group(FIRST_NODE, 2L * degree - midpoint), new Group(SECOND_NODE, 2L * degree));
			}
			try (LmdbPrefixRunCursor cursor = fixture.store.getPrefixRuns(txn, plan, -1, -1, -1, -1, true, true)) {
				cursor.stopBefore(new long[] { SECOND_NODE, FIRST_PREDICATE + 1, FIRST_NEIGHBOR + midpoint, 0 });
				assertThat(groups(cursor, fixture.groupField)).containsExactly(
						new Group(FIRST_NODE, 2L * degree), new Group(SECOND_NODE, degree + midpoint));
			}
			LmdbPrefixRunPlan.resetMetrics();
			try (LmdbPrefixRunCursor cursor = fixture.store.getPrefixRuns(txn, fixture.plan(7), -1, -1, -1, 7,
					true, true)) {
				long selected = 2L * ((degree + 2) / 3);
				assertThat(groups(cursor, fixture.groupField)).containsExactly(
						new Group(FIRST_NODE, selected), new Group(SECOND_NODE, selected));
			}
			assertThat(LmdbPrefixRunPlan.PERSISTED_METADATA_COUNTS.get())
					.as("node/predicate totals cannot answer a residual context constraint")
					.isZero();
		}
	}

	private static Work groupedWork(Path directory, boolean incoming, int degree) throws Exception {
		try (Fixture fixture = new Fixture(directory, incoming, degree); Txn txn = fixture.snapshot()) {
			LmdbPrefixRunPlan plan = fixture.plan(-1);
			LmdbPrefixRunPlan.resetMetrics();
			try (LmdbStartupReadCounter reads = new LmdbStartupReadCounter()) {
				try (LmdbPrefixRunCursor cursor = fixture.store.getPrefixRuns(txn, plan, -1, -1, -1, -1, true, true)) {
					assertThat(groups(cursor, fixture.groupField)).containsExactly(
							new Group(FIRST_NODE, 2L * degree), new Group(SECOND_NODE, 2L * degree));
				}
				Map<String, Long> nativeWork = reads.operations();
				return new Work(LmdbPrefixRunPlan.ROWS_SCANNED.get(), LmdbPrefixRunPlan.PERSISTED_METADATA_COUNTS.get(),
						nativeWork.getOrDefault("mdb_get", 0L), nativeWork.getOrDefault("mdb_cursor_open", 0L),
						nativeWork.getOrDefault("mdb_cursor_get", 0L));
			}
		}
	}

	private static List<Group> groups(LmdbPrefixRunCursor cursor, int field) throws Exception {
		List<Group> groups = new ArrayList<>();
		while (cursor.next()) {
			groups.add(new Group(cursor.prefixValue(field), cursor.runRowCount()));
		}
		return groups;
	}

	private record Group(long node, long count) {
	}

	private record Work(long representatives, long metadataAnswers, long pointReads, long cursorOpens,
			long cursorReads) {
	}

	private static final class Fixture implements AutoCloseable {
		final TripleStore store;
		final int groupField;

		Fixture(Path directory, boolean incoming, int degree) throws Exception {
			Files.createDirectories(directory);
			groupField = incoming ? TripleIndex.OBJ_IDX : TripleIndex.SUBJ_IDX;
			store = new TripleStore(directory.toFile(), new LmdbStoreConfig("psoc,posc")
					.setDirectAdjacencyEnabled(false), null);
			try {
				store.startTransaction();
				for (long node : new long[] { FIRST_NODE, SECOND_NODE }) {
					for (long predicate = FIRST_PREDICATE; predicate <= FIRST_PREDICATE + 1; predicate++) {
						for (int ordinal = 0; ordinal < degree; ordinal++) {
							long neighbor = FIRST_NEIGHBOR + ordinal;
							assertThat(store.storeTriple(incoming ? neighbor : node, predicate,
									incoming ? node : neighbor, ordinal % 3 == 0 ? 7 : 0, true)).isTrue();
						}
					}
				}
				assertThat(store.storeTriple(incoming ? 90_000 : FIRST_NODE, FIRST_PREDICATE,
						incoming ? FIRST_NODE : 90_000, 7, false)).isTrue();
				LmdbPersistentAdjacency.openExisting(store.writeTxn).compact(store.writeTxn, true);
				store.commit();
			} catch (Throwable failure) {
				store.close();
				throw failure;
			}
		}

		LmdbPrefixRunPlan plan(long context) {
			LmdbPrefixRunPlan plan = store.prefixRunPlan(new int[] { groupField }, -1, -1, -1, context);
			assertThat(plan).isNotNull();
			assertThat(plan.index().toString()).isEqualTo(groupField == TripleIndex.SUBJ_IDX ? "spoc" : "opsc");
			return plan;
		}

		Txn snapshot() throws Exception {
			return store.getTxnManager().createReadTxnPinned(store::getDataRevision);
		}

		@Override
		public void close() throws Exception {
			store.close();
		}
	}
}
